CREATE TABLE IF NOT EXISTS companies(id INTEGER PRIMARY KEY AUTOINCREMENT, codigo_siagri TEXT, razao TEXT, fantasia TEXT, cnpj TEXT, status TEXT DEFAULT 'Ativa');
CREATE TABLE IF NOT EXISTS employees(id INTEGER PRIMARY KEY AUTOINCREMENT, company_id INTEGER, nome TEXT, cpf TEXT, matricula TEXT, cargo TEXT, centro_custo TEXT, codigo_correntista TEXT, status TEXT DEFAULT 'Ativo');
CREATE TABLE IF NOT EXISTS rubrics(id INTEGER PRIMARY KEY AUTOINCREMENT, company_id INTEGER, codigo TEXT, descricao TEXT, tipo TEXT, conta_debito TEXT, conta_credito TEXT, historico_id TEXT, historico TEXT, status TEXT DEFAULT 'Ativa', debito_gera_cc INTEGER DEFAULT 1, debito_gera_cor INTEGER DEFAULT 1, credito_gera_cc INTEGER DEFAULT 1, credito_gera_cor INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS chart_accounts(id INTEGER PRIMARY KEY AUTOINCREMENT, company_id INTEGER, conta TEXT, descricao TEXT, utiliza_cc INTEGER DEFAULT 0, tipo_correntista TEXT DEFAULT '9-Nenhum', gera_cor INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS finance_params(id INTEGER PRIMARY KEY AUTOINCREMENT, company_id INTEGER, tipo TEXT, documento_id TEXT, parceiro_cpf_cnpj TEXT, codigo_parceiro_siagri TEXT, conta_contrapartida TEXT, centro_custo TEXT, vencimento_dia INTEGER, historico TEXT, ativo INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS imports(id INTEGER PRIMARY KEY AUTOINCREMENT, company_id INTEGER, competencia TEXT, arquivo TEXT, data_hora TEXT, status TEXT);
CREATE TABLE IF NOT EXISTS payroll_lines(id INTEGER PRIMARY KEY AUTOINCREMENT, import_id INTEGER, company_id INTEGER, cpf TEXT, nome TEXT, cargo TEXT, codigo_verba TEXT, verba TEXT, referencia TEXT, valor NUMERIC, tipo TEXT, liquido NUMERIC DEFAULT 0);
